);


INSERT INTO clinicalcases (
    clinicalcaseid, patientid, title, type,
    description, symptom, medicalhistory, pe,
    status, createdBy
)
VALUES (
    '27747379', '11585755', 'Drug induced pancreatitis Drug induced dermatitis v viral exanthum', 'OTHER_ABDOMINAL',
    'A patient was admitted via ew emer. for evaluation of abdominal symptoms, later diagnosed with abdominal pathology.', 'Ms ___ is s/p aortic root, ascending aorta and hemiarch replacement on ___ with Dr. ___.  Her dialated aorta was due to large vessel aortitis.  Her post op course was uneventful and she was discharged home on POD 6.  She presented to the ED on ___ for fever up to 101, cough and chest/back pain.   She had a CTA and echocardiogram which were unremarkable and it was thought that she needed to increase her pain medication and concentrate on pulmonary toilet.  Shortly after leaving the ED she developed total body itching and rash which progressed to peeling skin on her back and arms.  She took benadryl at home with no relief.  She states her face feels swollen but denies difficulty breathing or throat swelling.  She states that she feels better after the solumedrol/benadryl/pepcid.  Her temp on arrival to ED was 102. She is also c/o nausea and R sided pain which she has had since surgery.', '- s/p aortic root, ascending aorta and hemiarch replacement on   ___ with Dr. ___. - Para 1 ___ 2(twins) - s/p tubal ligation   Social History: ___ Family History: mother has breast cancer, denies FH of SLE or other  rheumatologic disease', '[VITALS] Temp: NA BP: 106/57 HR: 87 O2Sat: 87 Weight: NA  [EXAM] Pulse:87 Resp:16  O2 sat:98%  B/P  Right:106/57   Left:  Height:     Weight:  General: Skin: diffuse macular papular rash w/areas of exfoliation on  arms and back, painful to palpation mouth w/areas of white plaques on tongue w/ulcers on L lateral surface Chest: Lungs clear bilaterally [x] Heart: RRR [x]  Irregular []  Murmur Abdomen: Soft [x] non-distended [x] +tender to palpation over upper abdomen, no guarding, no rebound  bowel sounds + [x] Extremities: Warm [x], well-perfused [x]  Edema Varicosities: None [x] Neuro: Grossly intact[x] Sternal incision clean and dry with no drainage or erythema',
    'active', 'system_generator'
);


INSERT INTO clinicalcases (
