INSERT INTO clinicalcases (
    clinicalcaseid, patientid, title, type,
    description, symptom, medicalhistory, pe,
    status, createdBy
)
VALUES (
    '25045274', '11925563', 'Acute appendicitis', 'APPENDICITIS',
    'A patient was admitted via eu observation for evaluation of abdominal symptoms, later diagnosed with acute appendicitis.', 'Mrs ___ is a ___ woman with a hx of SVT (previously  offered ablation but patient declined) presenting with  epigastric abdominal pain, bloating, and nausea since last  evening. According to the patient, ___ weeks ago she had acute  RLQ abdominal pain and went to ___ where workup (including a CT abdomen/pelvis) was reportedly normal. Her pain  eventually resolved on its own. Yesterday, she noted abdominal  bloating in the afternoon and then after dinner around 6pm she  felt epigastric abdominal pain that became progressively worse  and eventually localized to the RLQ. This was associated with  nausea but no vomiting. No changes in bowel habits or diarrhea.  ROS: Denies fevers, chills, SOB, CP, HA, dysuria, urinary  frequency/urgency, melena, hematochezia.', 'Chronic palpitations & SVT (was offered ablation but ultimately  declined; patient reports no cardiac complications with  anesthesia), breast cancer, chronic constipation, uterine  prolapse, borderline (diet controlled) diabetes, last  colonoscopy ___ was completely normal.  PSH: R mastectomy, hysterectomy, tonsillectomy, ovarian cysts   Social History: ___ Family History: Both her children have Wolfram''s syndrome and AVNRT.', '[VITALS] Temp: 98.1 BP: 132/76 HR: 78 O2Sat: 98 Weight: NA  [EXAM] VS: T 98.1, HR 78, BP 132/76, RR 16, O2 sat 97 RA GEN: Alert and oriented, no acute distress, conversant and  interactive. HEENT: Sclerae anicteric, mucous membranes moist, oropharynx is  clear. NECK: Trachea is midline, thyroid unremarkable, no palpable  cervical lymphadenopathy, no visible JVD. CV: Regular rate and rhythm, no audible murmurs. PULM/CHEST: Clear to auscultation bilaterally, respirations are  unlabored on room air. ABD: Soft, nondistended, minimally and appropriately tender to  palpation, no rebound or guarding, nontympanitic, no palpable  masses, dressings over incisions are clean and dry. Ext: No lower extremity edema, distal extremities feel warm and  appear well-perfused.',
    'active', 'system_generator'
);


INSERT INTO clinicalcases (
