INSERT INTO radiologyreport (
    clinicalcaseid, noteid, modality,
    region, examname, text
)
VALUES (
    '20849847',
    '11533366-RR-344',
    'CT',
    'Head',
    'CT HEAD W/O CONTRAST',
    'TECHNIQUE: Continuous axial MDCT images were obtained through the brain without the administration of IV contrast.  Sagittal, coronal, and thin-section bone reformatted images were obtained and reviewed.  FINDINGS: There is no evidence of hemorrhage, edema, mass effect, or large vascular territory infarction.  The ventricles and sulci are enlarged, consistent with age-related volume loss.  This is unchanged from the prior exam.  Periventricular confluent white matter hypodensities are consistent with chronic small vessel ischemic disease.  There is an unchanged lacunar infarct in the left basal ganglia, and either a second lacunar infarct or prominent vascular space in the right basal ganglia.  No fracture is identified.  The visualized paranasal sinuses, mastoid air cells, and middle ear cavities are clear.  The soft tissues are unremarkable.'
);


INSERT INTO radiologyreport (
