INSERT INTO radiologyreport (
    clinicalcaseid, noteid, modality,
    region, examname, text
)
VALUES (
    '21310093',
    '11190737-RR-24',
    'MRI',
    'Head',
    'MR HEAD W & W/O CONTRAST',
    'EXAMINATION: MR HEAD W AND W/O CONTRAST:  TECHNIQUE: Sagittal and axial T1 weighted imaging were performed. After administration of 7 mL of Gadavist intravenous contrast, axial imaging was performed with gradient echo, FLAIR, diffusion, and T1 technique. Sagittal MPRAGE imaging was performed and re-formatted in axial and coronal orientations.  FINDINGS: There is no evidence of hemorrhage, edema, masses, mass effect, midline shift or infarction.   The ventricles and sulci are normal in caliber and configuration.  Few scattered subcortical and periventricular white matter T2/FLAIR hyperintensities are nonspecific, however likely represent sequela of chronic small vessel ischemic disease.  One FLAIR hyperintensity specifically within the left aspect of the pons with associated high signal on both diffusion and ADC map, suggesting T2 shine through.  There is no abnormal enhancement after contrast administration.  The visualized portion of the paranasal sinuses are clear.  The orbits are grossly unremarkable.'
);


INSERT INTO radiologyreport (
    clinicalcaseid, noteid, modality,
