INSERT INTO radiologyreport (
    clinicalcaseid, noteid, modality,
    region, examname, text
)
VALUES (
    '28627153',
    '10207476-RR-68',
    'CT',
    'Chest',
    'CHEST (PORTABLE AP)',
    'EXAMINATION: Portable upright chest radiograph.  FINDINGS: There is increased lucency overlying the liver within the right upper quadrant that is concerning for possible intraperitoneal free air. There is bibasilar atelectasis.  There is mild increase in opacity that silhouettes the aorta in the leftward retrocardiac region that could represent atelectatic changes; however, pneumonia cannot be excluded.  There is a left ventricular configuration of the heart with tortuosity of the aorta.  The mediastinal contours are stable.  The visualized osseous structures are unremarkable.'
);


